INSERT INTO gm.exercise_revision ("exercise_id","revision","type","payload","rubric","normalization_version","provenance","review_status") VALUES ('30000000-0000-4000-8000-000000000100',1,'short_answer','{"id":"30000000-0000-4000-8000-000000000100","hint":{"de":"Schreiben Sie das Nomen groß.","en":"Keep the noun capitalized."},"type":"short_answer","prompt":"Wie lautet der Plural von „der Beruf“?","revision":1,"targetId":"30000000-0000-4000-8000-000000000200","instruction":{"de":"Schreiben Sie den Plural.","en":"Type the plural."},"schemaVersion":1}','{"explanation":{"de":"Der Plural lautet „Berufe“; Nomen werden großgeschrieben.","en":"The plural is „Berufe“; nouns retain capitalization."},"acceptedAnswers":[{"text":"Berufe","type":"short_answer"}],"normalizationVersion":"de-nfc-trim-v1"}','de-nfc-trim-v1','Original German Master renovation starter content; agent editorial checks of grammar and rubrics; owner-authorized production-first release, 6 October 2026. Independent German review remains pending.','approved');
INSERT INTO gm.exercise_revision ("exercise_id","revision","type","payload","rubric","normalization_version","provenance","review_status") VALUES ('30000000-0000-4000-8000-000000000101',1,'choice','{"id":"30000000-0000-4000-8000-000000000101","hint":{"de":"„Mit“ verlangt den Dativ.","en":"„Mit“ takes the dative."},"type":"choice","prompt":"Ich spreche mit ___ neuen Kollegen. (Ein Kollege.)","options":[{"id":"der","text":"der"},{"id":"den","text":"den"},{"id":"dem","text":"dem"}],"revision":1,"targetId":"30000000-0000-4000-8000-000000000201","instruction":{"de":"Wählen Sie den Artikel im Dativ Singular.","en":"Choose the singular dative article."},"schemaVersion":1}','{"explanation":{"de":"„Mit“ verlangt den Dativ. Bei einem Kollegen heißt es „dem neuen Kollegen“.","en":"„Mit“ takes the dative. For one colleague, use „dem neuen Kollegen“."},"acceptedAnswers":[{"type":"choice","optionId":"dem"}],"normalizationVersion":"de-nfc-trim-v1"}','de-nfc-trim-v1','Original German Master renovation starter content; agent editorial checks of grammar and rubrics; owner-authorized production-first release, 6 October 2026. Independent German review remains pending.','approved');
INSERT INTO gm.exercise_revision ("exercise_id","revision","type","payload","rubric","normalization_version","provenance","review_status") VALUES ('30000000-0000-4000-8000-000000000102',1,'cloze','{"id":"30000000-0000-4000-8000-000000000102","hint":{"de":"Denken Sie an das Ziel.","en":"Think of the destination."},"type":"cloze","slots":[{"id":"preposition","label":"Präposition"}],"prompt":"Ich fahre mit dem Bus ___ Büro.","revision":1,"targetId":"30000000-0000-4000-8000-000000000202","instruction":{"de":"Ergänzen Sie die Präposition.","en":"Complete the preposition."},"schemaVersion":1}','{"explanation":{"de":"Ein Ziel mit „das Büro“ verlangt „in das“, meist verkürzt zu „ins“.","en":"A destination with „das Büro“ uses „in das“, usually „ins“."},"acceptedAnswers":[{"type":"cloze","values":[{"text":"ins","slotId":"preposition"}]},{"type":"cloze","values":[{"text":"in das","slotId":"preposition"}]}],"normalizationVersion":"de-nfc-trim-v1"}','de-nfc-trim-v1','Original German Master renovation starter content; agent editorial checks of grammar and rubrics; owner-authorized production-first release, 6 October 2026. Independent German review remains pending.','approved');
INSERT INTO gm.exercise_revision ("exercise_id","revision","type","payload","rubric","normalization_version","provenance","review_status") VALUES ('30000000-0000-4000-8000-000000000103',1,'word_order','{"id":"30000000-0000-4000-8000-000000000103","hint":{"de":"Das konjugierte Verb steht am Ende.","en":"The conjugated verb comes last."},"type":"word_order","prompt":"Büro / weil / heute / ich / im / arbeite","tokens":[{"id":"0","text":"Büro"},{"id":"1","text":"weil"},{"id":"2","text":"heute"},{"id":"3","text":"ich"},{"id":"4","text":"im"},{"id":"5","text":"arbeite"}],"revision":1,"targetId":"30000000-0000-4000-8000-000000000203","instruction":{"de":"Ordnen Sie die Wörter. Setzen Sie „heute“ direkt nach „ich“.","en":"Order the words. Put „heute“ immediately after „ich“."},"schemaVersion":1}','{"explanation":{"de":"Nach „weil“ steht das konjugierte Verb am Ende.","en":"After „weil“, the conjugated verb goes to the end."},"acceptedAnswers":[{"type":"word_order","tokenIds":["1","3","2","4","0","5"]}],"normalizationVersion":"de-nfc-trim-v1"}','de-nfc-trim-v1','Original German Master renovation starter content; agent editorial checks of grammar and rubrics; owner-authorized production-first release, 6 October 2026. Independent German review remains pending.','approved');
INSERT INTO gm.exercise_revision ("exercise_id","revision","type","payload","rubric","normalization_version","provenance","review_status") VALUES ('30000000-0000-4000-8000-000000000104',1,'multi_slot','{"id":"30000000-0000-4000-8000-000000000104","hint":{"de":"Achten Sie auf die Endungen nach dem Stamm „arbeit-“.","en":"Watch the endings after the stem „arbeit-“."},"type":"multi_slot","slots":[{"id":"du","label":"du"},{"id":"ihr","label":"ihr"}],"prompt":"Ergänzen Sie im Präsens: Du ___ früh. Ihr ___ früh.","revision":1,"targetId":"30000000-0000-4000-8000-000000000204","instruction":{"de":"Ergänzen Sie beide Formen von „arbeiten“.","en":"Complete both forms of „arbeiten“."},"schemaVersion":1}','{"explanation":{"de":"Bei „arbeiten“ steht vor -st und -t ein e: arbeitest, arbeitet.","en":"„Arbeiten“ adds an e before -st and -t: arbeitest, arbeitet."},"acceptedAnswers":[{"type":"multi_slot","values":[{"text":"arbeitest","slotId":"du"},{"text":"arbeitet","slotId":"ihr"}]}],"normalizationVersion":"de-nfc-trim-v1"}','de-nfc-trim-v1','Original German Master renovation starter content; agent editorial checks of grammar and rubrics; owner-authorized production-first release, 6 October 2026. Independent German review remains pending.','approved');
